insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_remote_control','remote control','noun','a small handheld device used to operate a television or other machine from a distance','[{"senseId":"remote_control_1","meaning":"a small handheld device used to operate a television or other machine from a distance","acceptedParaphrases":["controller","handheld device for controlling something"],"masteryContexts":[{"contextId":"u2_21_remote_control_meaning","text":"Pass me the remote control so I can turn the volume down.","meaning":"a handheld device for operating a machine from a distance","wrongMeanings":["a switch fixed to the side of a machine","a cable that connects a machine to a socket","a screen that shows what a machine is doing"]},{"contextId":"u2_21_remote_control_paraphrase","text":"The drone has a remote control with two small joysticks.","meaning":"a device used to operate something from a distance","wrongMeanings":["a camera that records what a drone sees","a battery that powers the drone in flight","a case that protects the drone when stored"]}],"situationDistractors":["Dad walked across the room and pressed the button on the television itself.","Mum searched the kitchen drawer for spare batteries.","The engineer plugged a long cable into the back of the machine.","The family sat around the table and played a board game after dinner.","The shop assistant fixed the new television to the wall with four strong screws.","Mum plugged in the lamp and moved the sofa closer to the window."],"gapDistractors":[{"contextId":"u2_21_remote_control_gap_1","answer":"remote control","wrong":["torch","newspaper","kettle"]},{"contextId":"u2_21_remote_control_gap_2","answer":"remote control","wrong":["kettle","window","radiator"]},{"contextId":"u2_21_remote_control_gap_3","answer":"remote control","wrong":["steering wheel","metal key","paintbrush"]}],"spellingErrors":["remot control","remote contrel","remote controll","remoat control","remote cotrol","remote contol"],"masteryPassages":[{"passageId":"u2_21_remote_control_passage_1","contextId":"u2_21_remote_control_gap_1","text":"The family sat down to watch a film, but the television stayed on the wrong channel. After ten minutes of searching under the sofa cushions, Dad finally found the ____ and pressed the button.","answer":"remote control"},{"passageId":"u2_21_remote_control_passage_2","contextId":"u2_21_remote_control_gap_2","text":"The toy helicopter hovered above the garden while the boy stood on the grass. He steered it left and right using the ____ in his hands.","answer":"remote control"}],"contextDependentParaphrases":[],"wrongParaphrases":["battery","screen","antenna"],"misleadingDistractors":["a switch fixed to a wall","a long cable between two machines","a person who manages a television programme"]}]'::jsonb,'[]'::jsonb,'["remote-control car","universal remote","wireless remote"]'::jsonb,'live'),
('vocab_feature','feature','noun','an important or noticeable part or quality of something','[{"senseId":"feature_1","meaning":"an important or noticeable part or quality of something","acceptedParaphrases":["characteristic","quality"],"masteryContexts":[{"contextId":"u2_22_feature_meaning","text":"Waterproofing is a useful feature of the new jacket.","meaning":"a useful part or quality of a product","wrongMeanings":["a fault that makes a product unsafe","a price that makes a product attractive","a review that helps people choose a product"]},{"contextId":"u2_22_feature_paraphrase","text":"The lake is the main feature of the park.","meaning":"a noticeable part of a place","wrongMeanings":["a rule that visitors must follow","a map that shows the way around","a danger that visitors must avoid"]}],"situationDistractors":["The shop sold the phone at half price during the sale.","A technician repaired the screen of the broken tablet.","The customer complained that the delivery arrived two days late.","The carpenter measured the wood twice before cutting the shelf to length.","The company announced a new price for its monthly subscription.","The reviewer spent a week testing the phone and then posted her opinion online."],"gapDistractors":[{"contextId":"u2_22_feature_gap_1","answer":"feature","wrong":["owner","warranty","receipt"]},{"contextId":"u2_22_feature_gap_2","answer":"feature","wrong":["price","owner","mistake"]},{"contextId":"u2_22_feature_gap_3","answer":"feature","wrong":["owner","visitor","mistake"]}],"spellingErrors":["featur","feture","feeature","featuer","fearture","feachure"],"masteryPassages":[{"passageId":"u2_22_feature_passage_1","contextId":"u2_22_feature_gap_1","text":"Customers compared three laptops before buying one. The deciding ____ was the battery, which could last for fifteen hours on a single charge.","answer":"feature"},{"passageId":"u2_22_feature_passage_2","contextId":"u2_22_feature_gap_2","text":"The hotel is not especially large or cheap. Its best ____, according to most guests, is the garden terrace overlooking the sea.","answer":"feature"}],"contextDependentParaphrases":[],"wrongParaphrases":["mistake","warning","guarantee"],"misleadingDistractors":["a mistake in a design","a person who tests products","the price of something"]}]'::jsonb,'[]'::jsonb,'["key feature","safety feature","special feature"]'::jsonb,'live'),
('vocab_function','function','noun','the purpose or job that something has; what it is designed to do','[{"senseId":"function_1","meaning":"the purpose or job that something has; what it is designed to do","acceptedParaphrases":["purpose","job"],"masteryContexts":[{"contextId":"u2_23_function_meaning","text":"What is the function of this switch?","meaning":"what it is for","wrongMeanings":["what it looks like","how much it costs","where it was made"]},{"contextId":"u2_23_function_paraphrase","text":"The function of the committee is to advise the principal.","meaning":"the purpose or job of a group","wrongMeanings":["the name or title of a group","the size and age of a group","the history and origin of a group"]}],"situationDistractors":["The designer chose bright colours to make the poster look attractive.","The company paid a lot to manufacture the new machine.","The user guide warned that the device could overheat.","The architect drew the plan of the new school hall on large sheets of paper.","The workers painted the machine bright yellow so that it could be seen in the dark.","The manufacturer recalled the product because customers had complained about the quality."],"gapDistractors":[{"contextId":"u2_23_function_gap_1","answer":"function","wrong":["colour","price","weight"]},{"contextId":"u2_23_function_gap_2","answer":"function","wrong":["colour","price","weight"]},{"contextId":"u2_23_function_gap_3","answer":"function","wrong":["colour","price","shape"]}],"spellingErrors":["funtion","fuction","funcion","functon","functoin","funccion"],"wordFamilyForms":[{"form":"function","partOfSpeech":"noun","example":"The function of a hinge is to let a door swing open.","pedagogicallyUseful":true},{"form":"functional","partOfSpeech":"adjective","example":"The kitchen is small but perfectly functional.","pedagogicallyUseful":true,"altExample":"Designers want products to look good and also be functional."},{"form":"malfunction","partOfSpeech":"noun","example":"A malfunction in the software caused the system to crash.","pedagogicallyUseful":true,"altExample":"The engineer reported a serious malfunction in the lift."}],"masteryPassages":[{"passageId":"u2_23_function_passage_1","contextId":"u2_23_function_gap_1","text":"Every part of the human body does something important. The ____ of the lungs is to take oxygen from the air and pass it into the blood.","answer":"function"},{"passageId":"u2_23_function_passage_2","contextId":"u2_23_function_gap_2","text":"Ella pressed every button on the new camera, but she could not work out what each one did. She asked her brother to explain the ____ of the small red one.","answer":"function"}],"contextDependentParaphrases":[],"wrongParaphrases":["design","price","size"],"misleadingDistractors":["the way something looks","the cost of making something","a danger to users"]}]'::jsonb,'["functional","malfunction"]'::jsonb,'["main function","basic function","vital function"]'::jsonb,'live'),
('vocab_interactive','interactive','adjective','allowing users to take part and respond, rather than just watch or read','[{"senseId":"interactive_1","meaning":"allowing users to take part and respond, rather than just watch or read","acceptedParaphrases":["hands-on","two-way"],"masteryContexts":[{"contextId":"u2_24_interactive_meaning","text":"The interactive whiteboard responds when students touch the screen.","meaning":"reacting to what the user does","wrongMeanings":["designed to be used by teachers only","able to show pictures in colour","fixed to the wall of a room"]},{"contextId":"u2_24_interactive_paraphrase","text":"Students stay more engaged when a lesson is interactive instead of a long lecture.","meaning":"involving active participation","wrongMeanings":["taking place outside the school","led entirely by one speaker","recorded for later viewing"]}],"situationDistractors":["The visitors walked past glass cases and read the label on each object.","The teacher talked for an hour while the students listened in silence.","The film played in the museum without anyone being able to change it.","The audience sat in rows and listened to the speaker without asking anything.","The teacher handed back the marked essays and asked everyone to read the comments silently.","The class watched a video about volcanoes and then went home for the weekend."],"gapDistractors":[{"contextId":"u2_24_interactive_gap_1","answer":"interactive","wrong":["passive","silent","printed"]},{"contextId":"u2_24_interactive_gap_2","answer":"interactive","wrong":["recorded","silent","printed"]},{"contextId":"u2_24_interactive_gap_3","answer":"interactive","wrong":["static","silent","printed"]}],"spellingErrors":["intaractive","interactiv","interactave","intreractive","interractive","interective"],"wordFamilyForms":[{"form":"interactive","partOfSpeech":"adjective","example":"The website has several interactive maps that respond to clicks.","pedagogicallyUseful":true},{"form":"interact","partOfSpeech":"verb","example":"Babies learn quickly when adults interact with them.","pedagogicallyUseful":true,"altExample":"Visitors can interact with the exhibits by touching the screens."},{"form":"interaction","partOfSpeech":"noun","example":"Face-to-face interaction is important for young children.","pedagogicallyUseful":true,"altExample":"Online games give players more interaction with each other."}],"masteryPassages":[{"passageId":"u2_24_interactive_passage_1","contextId":"u2_24_interactive_gap_1","text":"At the science museum, visitors do not just look at the displays. They can touch the screens, answer questions and change the experiment, which makes the exhibits much more ____.","answer":"interactive"},{"passageId":"u2_24_interactive_passage_2","contextId":"u2_24_interactive_gap_2","text":"A recorded lecture keeps students silent for an hour. By contrast, a really ____ lesson lets them vote, ask questions and work in small groups.","answer":"interactive"}],"contextDependentParaphrases":[],"wrongParaphrases":["automatic","pre-recorded","one-way"],"misleadingDistractors":["too complicated to use","available only to teachers","working without electricity"]}]'::jsonb,'["interact","interaction"]'::jsonb,'["interactive whiteboard","interactive display","interactive learning"]'::jsonb,'live'),
('vocab_widespread','widespread','adjective','found or happening in many places or among many people','[{"senseId":"widespread_1","meaning":"found or happening in many places or among many people","acceptedParaphrases":["common","found everywhere"],"masteryContexts":[{"contextId":"u2_25_widespread_meaning","text":"There was widespread flooding after three days of rain.","meaning":"happening in many places","wrongMeanings":["limited to one small area","caused by a sudden accident","expected by local people"]},{"contextId":"u2_25_widespread_paraphrase","text":"The idea has widespread support among parents.","meaning":"shared by many people","wrongMeanings":["kept secret by a few people","opposed by many people","explained by one person"]}],"situationDistractors":["Only one small village reported the unusual disease.","A rare bird was seen once in the north of the country.","The new rule applies to a single classroom.","The power cut affected one street for about twenty minutes.","A single student in the school caught a cold this week.","Only the village near the river lost its bridge in the storm."],"gapDistractors":[{"contextId":"u2_25_widespread_gap_1","answer":"widespread","wrong":["limited","occasional","private"]},{"contextId":"u2_25_widespread_gap_2","answer":"widespread","wrong":["limited","local","private"]},{"contextId":"u2_25_widespread_gap_3","answer":"widespread","wrong":["limited","rare","weak"]}],"spellingErrors":["widespred","widesprad","wydespread","widespreed","widdespread","widesread"],"masteryPassages":[{"passageId":"u2_25_widespread_passage_1","contextId":"u2_25_widespread_gap_1","text":"Heavy rain fell across the whole country for a week. The ____ flooding damaged roads, farms and homes in dozens of towns.","answer":"widespread"},{"passageId":"u2_25_widespread_passage_2","contextId":"u2_25_widespread_gap_2","text":"Ten years ago, only a few families owned a tablet. Today the use of tablets is ____, and almost every classroom has several.","answer":"widespread"}],"contextDependentParaphrases":[],"wrongParaphrases":["rare","temporary","harmful"],"misleadingDistractors":["spread out over a large wall","very rare","dangerous and harmful"]}]'::jsonb,'[]'::jsonb,'["widespread support","widespread damage","widespread use"]'::jsonb,'live'),
('vocab_availability','availability','noun','the fact that something can be obtained, used or reached','[{"senseId":"availability_1","meaning":"the fact that something can be obtained, used or reached","acceptedParaphrases":["supply","ease of obtaining"],"masteryContexts":[{"contextId":"u2_26_availability_meaning","text":"Check the availability of tickets before you travel.","meaning":"whether something can be obtained","wrongMeanings":["how much something costs","what something looks like","who is selling something"]},{"contextId":"u2_26_availability_paraphrase","text":"The availability of cheap flights has increased tourism.","meaning":"how easy it is to get or use something","wrongMeanings":["how safe something is to use","how long something lasts for","how popular something is with people"]}],"situationDistractors":["The quality of the chocolate was praised by every customer.","The shop doubled the price of its umbrellas when it started to rain.","The manual explained how to use the device safely.","The new phone received excellent reviews for its camera and screen.","The manager praised the staff for the friendly way they welcomed visitors.","The library changed the colour of its signs and moved the desk near the door."],"gapDistractors":[{"contextId":"u2_26_availability_gap_1","answer":"availability","wrong":["taste","colour","packaging"]},{"contextId":"u2_26_availability_gap_2","answer":"availability","wrong":["design","colour","packaging"]},{"contextId":"u2_26_availability_gap_3","answer":"availability","wrong":["colour","design","decoration"]}],"spellingErrors":["availablity","avalibility","availabilty","aviability","availibility","availabilaty"],"wordFamilyForms":[{"form":"availability","partOfSpeech":"noun","example":"The availability of fresh food is a problem in some regions.","pedagogicallyUseful":true},{"form":"available","partOfSpeech":"adjective","example":"Free wi-fi is available in every classroom.","pedagogicallyUseful":true,"altExample":"Only three rooms are still available for tonight."},{"form":"unavailable","partOfSpeech":"adjective","example":"The tickets were unavailable online after midday.","pedagogicallyUseful":true,"altExample":"The manager was unavailable because she was in a meeting."}],"masteryPassages":[{"passageId":"u2_26_availability_passage_1","contextId":"u2_26_availability_gap_1","text":"A farmer in a remote valley wanted to sell vegetables online, but there was no phone signal for kilometres. The poor ____ of the internet made the plan impossible.","answer":"availability"},{"passageId":"u2_26_availability_passage_2","contextId":"u2_26_availability_gap_2","text":"Before booking a hotel, check the ____ of rooms for your dates. In summer, the most popular hotels are often full months ahead.","answer":"availability"}],"contextDependentParaphrases":[],"wrongParaphrases":["demand","price","quality"],"misleadingDistractors":["the quality of something","the price of something","the danger of something"]}]'::jsonb,'["available","unavailable"]'::jsonb,'["limited availability","online availability","product availability"]'::jsonb,'live'),
('vocab_high_performance','high-performance','adjective','able to work at a very high standard or speed','[{"senseId":"high_performance_1","meaning":"able to work at a very high standard or speed","acceptedParaphrases":["very powerful","top-quality"],"masteryContexts":[{"contextId":"u2_27_high_performance_meaning","text":"The team uses high-performance cameras to film the race.","meaning":"able to work at a very high standard","wrongMeanings":["designed to be small and light","made to be cheap and simple","built to last for many years"]},{"contextId":"u2_27_high_performance_paraphrase","text":"Racing teams spend huge sums on high-performance engines.","meaning":"powerful and able to work at top speed","wrongMeanings":["cheap and easy to repair","quiet and kind to the environment","old but still in good condition"]}],"situationDistractors":["The old laptop froze whenever more than one program was open.","The shop sold simple calculators at a very low price.","The basic phone could only make calls and send texts.","The small family car was cheap to run and very easy to park in the city.","The old bicycle had a slow, squeaky chain and a broken brake.","The student bought a simple notebook and a pen for her first day at school."],"gapDistractors":[{"contextId":"u2_27_high_performance_gap_1","answer":"high-performance","wrong":["low-power","out-of-date","basic"]},{"contextId":"u2_27_high_performance_gap_2","answer":"high-performance","wrong":["low-power","basic","underpowered"]},{"contextId":"u2_27_high_performance_gap_3","answer":"high-performance","wrong":["low-cost","relaxed","occasional"]}],"spellingErrors":["high-preformance","high-performence","high-perfomance","high-performanse","high-peformance","high-performanc"],"masteryPassages":[{"passageId":"u2_27_high_performance_passage_1","contextId":"u2_27_high_performance_gap_1","text":"Most office computers are cheap and simple, because they only run email and documents. Video editors, however, need a ____ machine that can handle enormous files without slowing down.","answer":"high-performance"},{"passageId":"u2_27_high_performance_passage_2","contextId":"u2_27_high_performance_gap_2","text":"Formula One teams spend millions on their cars. Every ____ engine is tested for months so that it works at maximum speed in every race.","answer":"high-performance"}],"contextDependentParaphrases":[],"wrongParaphrases":["very expensive","very small","very old"],"misleadingDistractors":["cheap and basic","very old","small and light"]}]'::jsonb,'[]'::jsonb,'["high-performance engine","high-performance computer","high-performance car"]'::jsonb,'live'),
('vocab_stabilising','stabilising','adjective','making something steady and less likely to change suddenly or fall','[{"senseId":"stabilising_1","meaning":"making something steady and less likely to change suddenly or fall","acceptedParaphrases":["steadying","balancing"],"masteryContexts":[{"contextId":"u2_28_stabilising_meaning","text":"The calm teacher was a stabilising presence in the busy classroom.","meaning":"helping to keep things steady and calm","wrongMeanings":["making a situation busier and louder","causing students to compete harder","making lessons shorter and easier"]},{"contextId":"u2_28_stabilising_paraphrase","text":"The stabilising fins keep the rocket flying straight.","meaning":"keeping something steady and balanced","wrongMeanings":["making something faster and lighter","making something hotter and louder","making something larger and stronger"]}],"situationDistractors":["The sudden storm made the small boat rock violently from side to side.","The rumours caused panic and prices shot up.","The wobbly table collapsed when someone leaned on it.","The heavy rain made the river rise and flood the fields overnight.","The loud music woke the neighbours and caused a long argument.","A rumour about closing the factory spread quickly and worried the workers."],"gapDistractors":[{"contextId":"u2_28_stabilising_gap_1","answer":"stabilising","wrong":["disturbing","damaging","confusing"]},{"contextId":"u2_28_stabilising_gap_2","answer":"stabilising","wrong":["accelerating","decorative","warning"]},{"contextId":"u2_28_stabilising_gap_3","answer":"stabilising","wrong":["destabilising","inflationary","disruptive"]}],"spellingErrors":["stablising","stabillising","stabiliseing","stabalising","stabilisng","stebilising"],"wordFamilyForms":[{"form":"stabilising","partOfSpeech":"adjective","example":"The coach’s calm voice had a stabilising effect on the nervous team.","pedagogicallyUseful":true},{"form":"stabilise","partOfSpeech":"verb","example":"Doctors worked quickly to stabilise the patient before the journey.","pedagogicallyUseful":true},{"form":"stable","partOfSpeech":"adjective","example":"The ladder must be stable before anyone climbs it.","pedagogicallyUseful":true},{"form":"stability","partOfSpeech":"noun","example":"The country needs political stability to attract investors.","pedagogicallyUseful":true},{"form":"unstable","partOfSpeech":"adjective","example":"The unstable bridge was closed to traffic.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_28_stabilising_passage_1","contextId":"u2_28_stabilising_gap_1","text":"After weeks of arguments, the school council needed someone calm. The new head of year had a ____ effect on the whole group, and the meetings became peaceful again.","answer":"stabilising"},{"passageId":"u2_28_stabilising_passage_2","contextId":"u2_28_stabilising_gap_2","text":"The tall tower sways in strong winds. Engineers added a ____ system of heavy weights at the top, which stops the building moving too far from side to side.","answer":"stabilising"}],"contextDependentParaphrases":[],"wrongParaphrases":["weakening","speeding","tightening"],"misleadingDistractors":["causing sudden changes","making something larger","making something cheaper"]}]'::jsonb,'["stabilise","stable","stability","unstable"]'::jsonb,'["stabilising effect","stabilising influence","stabilising measure"]'::jsonb,'live'),
('vocab_multi_task','multi-task','verb','to do several jobs or activities at the same time','[{"senseId":"multi_task_1","meaning":"to do several jobs or activities at the same time","acceptedParaphrases":["do several things at once","do several jobs at once"],"masteryContexts":[{"contextId":"u2_29_multi_task_meaning","text":"Computers can multi-task by running many programs at once.","meaning":"do several things at the same time","wrongMeanings":["finish one thing before starting another","repeat the same thing many times","share one thing between several people"]},{"contextId":"u2_29_multi_task_paraphrase","text":"I cannot multi-task, so I finish one job before starting the next.","meaning":"do several jobs at the same time","wrongMeanings":["work very slowly on one job","ask for help with every job","change jobs very often"]}],"situationDistractors":["She finished the report completely before she opened her email.","He gave his whole attention to the lesson and ignored his phone.","Two colleagues shared one big job, each doing half.","He closed his email, turned off his phone and wrote the report from start to finish.","The two friends shared one large pizza and talked about their holidays.","The manager asked the new employee to focus on a single customer for the whole morning."],"gapDistractors":[{"contextId":"u2_29_multi_task_gap_1","answer":"multi-task","wrong":["relax","rest","retire"]},{"contextId":"u2_29_multi_task_gap_2","answer":"multi-task","wrong":["relax","rest","focus"]},{"contextId":"u2_29_multi_task_gap_3","answer":"multi-task","wrong":["relax","shut down","upgrade"]}],"spellingErrors":["multi task","mult-task","multi-tsak","multy-task","multi-taks","mutli-task"],"masteryPassages":[{"passageId":"u2_29_multi_task_passage_1","contextId":"u2_29_multi_task_gap_1","text":"Some students write an essay, listen to music and message friends all together. Research suggests that nobody can truly ____, because the brain really switches quickly between the jobs.","answer":"multi-task"},{"passageId":"u2_29_multi_task_passage_2","contextId":"u2_29_multi_task_gap_2","text":"A modern phone can run a map, a music player and a video call together. The reason is that the processor is designed to ____ without crashing.","answer":"multi-task"}],"contextDependentParaphrases":[],"wrongParaphrases":["do one thing slowly","do things in secret","do things for others"],"misleadingDistractors":["focus on one job only","finish a job early","share a job with a colleague"]}]'::jsonb,'[]'::jsonb,'["multi-task effectively","multi-task easily","cannot multi-task"]'::jsonb,'live'),
('vocab_predictable','predictable','adjective','happening or behaving in the way you expect; easy to know in advance','[{"senseId":"predictable_1","meaning":"happening or behaving in the way you expect; easy to know in advance","acceptedParaphrases":["easy to guess","expected"],"masteryContexts":[{"contextId":"u2_30_predictable_meaning","text":"Her reaction was entirely predictable.","meaning":"exactly what people expected","wrongMeanings":["very different from what people wanted","too sudden for people to notice","kinder than people deserved"]},{"contextId":"u2_30_predictable_paraphrase","text":"The weather in the desert is predictable: hot and dry.","meaning":"easy to know in advance","wrongMeanings":["difficult to live in for long","harmful to people and animals","different every single day"]}],"situationDistractors":["The result of the match surprised everyone in the stadium.","Nobody could guess which card the magician would choose.","The sudden announcement took the whole class by surprise.","The magician pulled a rabbit out of an empty box, and the children gasped.","Nobody could say what the new film would be about before the trailer came out.","The sudden thunderstorm ruined the outdoor concert on a sunny afternoon."],"gapDistractors":[{"contextId":"u2_30_predictable_gap_1","answer":"predictable","wrong":["surprising","unexpected","sudden"]},{"contextId":"u2_30_predictable_gap_2","answer":"predictable","wrong":["confusing","changeable","random"]},{"contextId":"u2_30_predictable_gap_3","answer":"predictable","wrong":["original","surprising","unusual"]}],"spellingErrors":["predicable","predictible","predictabel","predectable","preditable","predictabull"],"wordFamilyForms":[{"form":"predictable","partOfSpeech":"adjective","example":"The ending of the film was entirely predictable.","pedagogicallyUseful":true},{"form":"predict","partOfSpeech":"verb","example":"No one can predict exactly how technology will change our lives.","pedagogicallyUseful":true},{"form":"prediction","partOfSpeech":"noun","example":"Her prediction about the exam questions turned out to be correct.","pedagogicallyUseful":true},{"form":"unpredictable","partOfSpeech":"adjective","example":"Mountain weather can be dangerously unpredictable.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_30_predictable_passage_1","contextId":"u2_30_predictable_gap_1","text":"The film began with a hero, a villain and a chase. By the middle, everyone in the cinema knew how it would end, and the story felt completely ____.","answer":"predictable"},{"passageId":"u2_30_predictable_passage_2","contextId":"u2_30_predictable_gap_2","text":"Our bus arrives at exactly the same time every morning and takes the same route. Because the journey is so ____, I can plan my day to the minute.","answer":"predictable"}],"contextDependentParaphrases":[],"wrongParaphrases":["hard to believe","easy to forget","hard to find"],"misleadingDistractors":["happening by accident","full of surprises","impossible to understand"]}]'::jsonb,'["predict","prediction","unpredictable"]'::jsonb,'["highly predictable","entirely predictable","easily predictable"]'::jsonb,'live')
